import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# packet.ChangeMobProperty{EntityUniqueID: -5, Property: "minecraft:has_nectar", BoolValue: true,
# StringValue: "variant_b", IntValue: 300, FloatValue: 1.5}
HAS_NECTAR = bytes.fromhex("09146d696e6563726166743a6861735f6e6563746172010976617269616e745f62d8040000c03f")

# generated by gophertunnel b8bd735:
# packet.ChangeMobProperty{IntValue: -1}
NEGATIVE_INT = bytes.fromhex("000000000100000000")

GOLDENS = [
    pytest.param(
        v2225.ChangeMobPropertyPacket(
            actor_id=-5,
            prop_name="minecraft:has_nectar",
            bool_component_val=True,
            string_component_val="variant_b",
            int_component_val=300,
            float_component_val=1.5,
        ),
        HAS_NECTAR,
        id="has-nectar",
    ),
    pytest.param(v2225.ChangeMobPropertyPacket(int_component_val=-1), NEGATIVE_INT, id="negative-int"),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_change_mob_property_is_packet_182(version):
    assert version.PACKETS[182] is version.ChangeMobPropertyPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_change_mob_property_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_change_mob_property_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
